// Every queue the relay touches, in one shape. Three tables because three
// different things queue them (a submit transaction, a team leader's morning,
// a board's deadline sweep), but to the operator watching the relay they are
// one stream of "did it go". The figures and the list both read this — the
// same window over the same rows — so the card cannot say "실패 1건" and then
// list none.
//
// Only the columns the operator needs. The report's title and the reminder's
// origin stay in their own tables; nothing here joins to a report body.
const mailDeliveriesUnion = `
	SELECT 'REPORT' AS kind, d.id, d.user_id AS who, d.address, d.status, d.attempts,
		d.error_message, d.created_at, d.sent_at, to_char(r.week_start, 'YYYY-MM-DD') || ' 주 제출 메일' AS subject
	FROM report_mail_deliveries d JOIN weekly_reports r ON r.id = d.report_id
	UNION ALL
	SELECT 'TEAM_REMINDER', id, recipient_user_id, address, status, attempts,
		error_message, created_at, sent_at, to_char(week_start, 'YYYY-MM-DD') || ' 주 작성 권고'
	FROM team_reminder_deliveries
	UNION ALL
	SELECT 'SCHEDULE_REMINDER', id, user_id, address, status, attempts,
		error_message, created_at, sent_at, to_char(reminder_on, 'YYYY-MM-DD') || ' 마감 알림'
	FROM schedule_reminder_deliveries`

// adminMailHealth answers what has actually been happening to the mail.
//
// A writer sees their own deliveries; the operator who owns the relay saw
// nothing. So a relay that is refusing everybody looks, from the settings
// screen, exactly like one nobody has used yet — and the test button only says
// whether it works this second, not whether last Monday went out.
func (a *App) adminMailHealth(w http.ResponseWriter, r *http.Request) {
	view := mailHealthView{Days: mailHealthDays}
	if err := a.db.QueryRow(r.Context(), `
		SELECT
			count(*) FILTER (WHERE status = 'SENT'),
			count(*) FILTER (WHERE status = 'QUEUED'),
			count(*) FILTER (WHERE status = 'FAILED'),
			count(DISTINCT who),
			count(*) FILTER (WHERE kind = 'REPORT'),
			count(*) FILTER (WHERE kind = 'TEAM_REMINDER'),
			count(*) FILTER (WHERE kind = 'SCHEDULE_REMINDER')
		FROM (`+mailDeliveriesUnion+`) m
		WHERE created_at > now() - make_interval(days => $1)`, mailHealthDays).
		Scan(&view.Sent, &view.Queued, &view.Failed, &view.Writers,
			&view.ByKind.Report, &view.ByKind.TeamReminder, &view.ByKind.ScheduleReminder); err != nil {
		a.logger.Error("mail health", "error", err, "trace", traceIDFromContext(r.Context()))
		writeError(w, http.StatusInternalServerError, "QUERY_FAILED", "메일 발송 현황을 읽을 수 없습니다.")
		return
	}
	// The relay's own words, not a count. "3건 실패" sends an operator to a log;
	// "받는 주소를 릴레이가 거부했습니다: 550 …" sends them to the right place.
	if err := a.db.QueryRow(r.Context(), `
		SELECT coalesce(error_message, ''), created_at FROM (`+mailDeliveriesUnion+`) m
		WHERE error_message <> '' AND created_at > now() - make_interval(days => $1)
		ORDER BY created_at DESC LIMIT 1`, mailHealthDays).
		Scan(&view.LastError, &view.LastFailed); err != nil && !errors.Is(err, pgx.ErrNoRows) {
		a.logger.Error("mail health reason", "error", err, "trace", traceIDFromContext(r.Context()))
	}
	writeData(w, http.StatusOK, view)
}

// mailDeliveryLimit is how many recent rows the card shows. Enough to read a
// bad morning; anything older is in the queue tables.
const mailDeliveryLimit = 50

type mailDeliveryRow struct {
	Kind         string     `json:"kind"`
	UserName     string     `json:"userName"`
	Address      string     `json:"address"`
	Subject      string     `json:"subject"`
	Status       string     `json:"status"`
	Attempts     int        `json:"attempts"`
	ErrorMessage string     `json:"errorMessage"`
	CreatedAt    time.Time  `json:"createdAt"`
	SentAt       *time.Time `json:"sentAt"`
}

type mailDeliveryList struct {
	Days int `json:"days"`
	// The filter the server actually applied, echoed back. The screen captions
	// the table with what it asked for; if the server had quietly dropped a
	// condition, that caption would be a lie told over the rows disproving it.
	Status string `json:"status,omitempty"`
	Kind   string `json:"kind,omitempty"`
	// Set when the window held more rows than the page shows. A full page is
	// otherwise read as "this is all of the last 14 days", and the operator has
	// no way to know they should narrow further. Absent when nothing was
	// dropped, so the screen's notice cannot be standing furniture.
	Truncated bool              `json:"truncated,omitempty"`
	Items     []mailDeliveryRow `json:"items"`
}

// The names the three queues actually store — the CHECK constraints on their
// status columns, and the labels mailDeliveriesUnion gives each queue.
var (
	mailDeliveryStatuses = []string{"QUEUED", "SENT", "FAILED"}
	mailDeliveryKinds    = []string{"REPORT", "TEAM_REMINDER", "SCHEDULE_REMINDER"}
)

// mailDeliveryFilter reads one condition from the query. Uppercased, because
// this is as often typed into an address bar as picked from a select.
//
// An unreadable page size falls back to the default page; an unreadable filter
// cannot. clampQueryInt's caller still gets what it asked for, only less of it,
// but a status this deployment never stores has no nearest sensible answer —
// and the unfiltered page is the one answer that is actively wrong, because
// the screen has already captioned it 실패만.
func mailDeliveryFilter(r *http.Request, name string, allowed []string) (string, bool) {
	value := strings.ToUpper(strings.TrimSpace(r.URL.Query().Get(name)))
	if value == "" {
		return "", true
	}
	return value, slices.Contains(allowed, value)
}

// adminMailDeliveries lists what went to whom, and why it did not — the rows
// behind the figures, newest first. No body: the subject is made from a date,
// and the address is the one the writer already sees on their own screen.
//
// status and kind narrow it, and they are applied to the window rather than to
// the page. A good week is what hides a bad one: a deployment sending a
// hundred digests on a Monday fills the newest 50 with successes and pushes
// the single refusal the card is counting off the bottom. Filtering the page
// after the cut would hand back whichever failures happened to be in that 50,
// which on exactly the week the operator needs this is none of them.
func (a *App) adminMailDeliveries(w http.ResponseWriter, r *http.Request) {
	status, statusKnown := mailDeliveryFilter(r, "status", mailDeliveryStatuses)
	kind, kindKnown := mailDeliveryFilter(r, "kind", mailDeliveryKinds)
	if !statusKnown || !kindKnown {
		writeError(w, http.StatusBadRequest, "INVALID_FILTER",
			"발송 상태는 QUEUED·SENT·FAILED, 종류는 REPORT·TEAM_REMINDER·SCHEDULE_REMINDER 가운데 하나여야 합니다.")
		return
	}
	where := ""
	args := []any{mailHealthDays}
	if status != "" {
		args = append(args, status)
		where += fmt.Sprintf(" AND m.status = $%d", len(args))
	}
	if kind != "" {
		args = append(args, kind)
		where += fmt.Sprintf(" AND m.kind = $%d", len(args))
	}
	// One more than the page, and the extra row is never shown. Its existence is
	// the whole answer — asking a second query for a count would say how many
	// more there are, which is not a number the operator can act on, and a total
	// in the response is a page-size contract this list does not have.
	args = append(args, mailDeliveryLimit+1)
	rows, err := a.db.Query(r.Context(), `
		SELECT m.kind, u.display_name, m.address, m.subject, m.status, m.attempts,
			m.error_message, m.created_at, m.sent_at
		FROM (`+mailDeliveriesUnion+`) m JOIN users u ON u.id = m.who
		WHERE m.created_at > now() - make_interval(days => $1)`+where+`
		ORDER BY m.created_at DESC, m.id DESC
		LIMIT $`+strconv.Itoa(len(args)), args...)
	if err != nil {
		a.logger.Error("mail deliveries", "error", err, "trace", traceIDFromContext(r.Context()))
		writeError(w, http.StatusInternalServerError, "QUERY_FAILED", "메일 발송 기록을 읽을 수 없습니다.")
		return
	}
	defer rows.Close()
	list := mailDeliveryList{Days: mailHealthDays, Status: status, Kind: kind, Items: []mailDeliveryRow{}}
	for rows.Next() {
		if len(list.Items) == mailDeliveryLimit {
			list.Truncated = true
			break
		}
		var item mailDeliveryRow
		if err := rows.Scan(&item.Kind, &item.UserName, &item.Address, &item.Subject, &item.Status,
			&item.Attempts, &item.ErrorMessage, &item.CreatedAt, &item.SentAt); err != nil {
			a.logger.Error("mail deliveries", "error", err, "trace", traceIDFromContext(r.Context()))
			writeError(w, http.StatusInternalServerError, "QUERY_FAILED", "메일 발송 기록을 읽을 수 없습니다.")
			return
		}
		list.Items = append(list.Items, item)
	}
	if err := rows.Err(); err != nil {
		a.logger.Error("mail deliveries", "error", err, "trace", traceIDFromContext(r.Context()))
		writeError(w, http.StatusInternalServerError, "QUERY_FAILED", "메일 발송 기록을 읽을 수 없습니다.")
		return
	}
	writeData(w, http.StatusOK, list)
}
